import json
from typing import Any, Dict, List

from pydantic import BaseModel


_SCHEMA_FIELDS = {
    "type",
    "format",
    "description",
    "nullable",
    "enum",
    "items",
    "properties",
    "required",
    "minimum",
    "maximum",
    "minItems",
    "maxItems",
    "minLength",
    "maxLength",
    "pattern",
    "example",
    "anyOf",
    "propertyOrdering",
    "default",
}


def _clean_schema(value: Any) -> Any:
    if isinstance(value, list):
        return [_clean_schema(item) for item in value]
    if not isinstance(value, dict):
        return value

    cleaned = {}
    for key, item in value.items():
        if key not in _SCHEMA_FIELDS:
            continue
        if key == "properties" and isinstance(item, dict):
            cleaned[key] = {
                name: _clean_schema(schema) for name, schema in item.items()
            }
        else:
            cleaned[key] = _clean_schema(item)

    schema_type = cleaned.get("type")
    if isinstance(schema_type, list) and "null" in schema_type:
        non_null = [item for item in schema_type if item != "null"]
        cleaned["type"] = non_null[0] if len(non_null) == 1 else non_null
        cleaned["nullable"] = True
    return cleaned


def tool_declarations(tools: dict) -> List[Dict[str, Any]]:
    declarations = []
    for fallback_name, tool in tools.items():
        if not isinstance(tool, dict):
            continue
        spec = tool.get("spec") or {}
        if spec.get("type") == "function":
            spec = spec.get("function") or {}

        declaration = {"name": spec.get("name") or fallback_name}
        if spec.get("description"):
            declaration["description"] = spec["description"]
        if isinstance(spec.get("parameters"), dict):
            declaration["parameters"] = _clean_schema(spec["parameters"])
        declarations.append(declaration)
    return declarations


def _json_value(value: Any) -> Any:
    if isinstance(value, BaseModel):
        value = value.model_dump()
    return json.loads(json.dumps(value, default=str))


async def execute_tool(call: dict, tools: dict) -> Dict[str, Any]:
    name = call.get("name", "")
    tool = tools.get(name)
    response: Dict[str, Any]

    if not isinstance(tool, dict) or not callable(tool.get("callable")):
        response = {"error": f"Tool is unavailable: {name}"}
    else:
        arguments = call.get("args") or {}
        if not isinstance(arguments, dict):
            response = {"error": "Tool arguments must be an object."}
        else:
            try:
                result = await tool["callable"](**arguments)
                normalized = _json_value(result)
                response = (
                    normalized
                    if isinstance(normalized, dict)
                    else {"result": normalized}
                )
            except Exception as exc:
                response = {"error": str(exc)}

    function_response = {"name": name, "response": response}
    if call.get("id"):
        function_response["id"] = call["id"]
    return {"functionResponse": function_response}

# --- client.py ---

import json
from typing import Any, AsyncIterator, Dict, List
from urllib.parse import quote

import httpx


class AgentPlatformClient:
    async def stream_generate(
        self,
        model: str,
        payload: Dict[str, Any],
        *,
        api_key: str,
        base_url: str,
        timeout_seconds: float,
    ) -> AsyncIterator[Dict[str, Any]]:
        model_path = quote(model, safe="._-")
        url = (
            f"{base_url.rstrip('/')}/v1/publishers/google/models/"
            f"{model_path}:streamGenerateContent"
        )
        timeout = httpx.Timeout(timeout_seconds)

        async with httpx.AsyncClient(timeout=timeout) as client:
            async with client.stream(
                "POST",
                url,
                params={"alt": "sse", "key": api_key},
                headers={"Content-Type": "application/json"},
                json=payload,
            ) as response:
                if response.status_code >= 400:
                    raw_error = await response.aread()
                    raise RuntimeError(_upstream_error(response.status_code, raw_error))

                data_lines = []
                async for line in response.aiter_lines():
                    if not line:
                        if data_lines:
                            yield _decode_sse(data_lines)
                            data_lines = []
                        continue
                    if line.startswith("data:"):
                        data_lines.append(line[5:].lstrip())
                if data_lines:
                    yield _decode_sse(data_lines)


def _decode_sse(data_lines: List[str]) -> Dict[str, Any]:
    try:
        decoded = json.loads("\n".join(data_lines))
    except json.JSONDecodeError as exc:
        raise RuntimeError("Agent Platform returned malformed streaming data.") from exc
    if not isinstance(decoded, dict):
        raise RuntimeError("Agent Platform returned an unexpected streaming event.")
    return decoded


def _upstream_error(status_code: int, raw_error: bytes) -> str:
    message = raw_error.decode("utf-8", errors="replace")[:2000]
    try:
        error = json.loads(message).get("error", {})
        message = error.get("message") or message
    except (json.JSONDecodeError, AttributeError):
        pass
    return f"Agent Platform request failed ({status_code}): {message}"

